#!/usr/bin/env bash
# Deploy with health gate + auto-rollback. Generated by shared.deployment.DeployService.
# Usage: bash deploy.sh   (run on the server, from anywhere)
set -euo pipefail

REPO_DIR="/opt/sites/callagent"
IMAGE="callagent:latest"
HEALTH_URL="http://127.0.0.1:8000/health"
HEALTH_TIMEOUT=60
HEALTH_INTERVAL=2

if [ ! -f "$REPO_DIR/docker-compose.yml" ]; then
  echo "FATAL: no docker-compose.yml in $REPO_DIR" >&2
  exit 1
fi
cd "$REPO_DIR"

# docker-compose.yml interpolates variables from .env for the build args *and*
# the runtime secrets live here too. Deploying without it starts a stack that is
# only half configured and usually fails after the health gate, so stop first.
if [ ! -f "$REPO_DIR/.env" ]; then
  echo "FATAL: no .env in $REPO_DIR - refusing to deploy" >&2
  exit 1
fi

# Always ship current origin/main (when the checkout is a git repo): a
# stale checkout is how the 2026-10-20 dangwire deploy built and ran the
# PREVIOUS commit's images - this script used to deploy whatever the
# checkout happened to contain.
#
# fetch + reset --hard, NOT `git pull --ff-only`: the VPS checkout is a
# DEPLOY ARTIFACT, not a developer checkout. The app writes runtime state
# into the working tree (dangwire: data/indexing/submission_queue.json),
# and on 2026-10-28 `git pull` refused the deploy because the incoming
# commit tracked a file the app had written. A reset ships exactly the
# committed tree (and keeps the untracked .env), a pull negotiates with a
# working tree that does not need to be preserved.
if git -C "$REPO_DIR" rev-parse --git-dir >/dev/null 2>&1; then
  echo "==> Pull"
  DEPLOY_BRANCH="$(git -C "$REPO_DIR" rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
  case "$DEPLOY_BRANCH" in
    ""|HEAD) DEPLOY_BRANCH="main" ;;
  esac
  git -C "$REPO_DIR" fetch --quiet --prune origin "$DEPLOY_BRANCH"
  git -C "$REPO_DIR" reset --hard "origin/$DEPLOY_BRANCH"
fi

# The canonical shared checkout on the VPS is a DEPLOY ARTIFACT too. A
# shared/main change has to reach the running code with the deploy that
# ships it - on 2026-10-28 the dangwire app could not boot because the VPS
# still had the pre-fix shared code (the CircuitBreaker/RateLimaker call
# signatures), and nothing in the pipeline moved it forward: the site
# checkout was updated, the shared checkout was not.
#
# The first existing checkout wins, so a site can point at its own copy with
# SHARED_REPO_DIR. A missing checkout is not an error: a site that does not
# consume the shared package (dkapp) simply has nothing to update.
for SHARED_DIR in "${SHARED_REPO_DIR:-}" /opt/sites/shared-canonical-services /opt/shared-canonical-services; do
  [ -n "$SHARED_DIR" ] || continue
  [ -d "$SHARED_DIR/.git" ] || continue
  echo "==> Pull shared ($SHARED_DIR)"
  # Every site deploy pulls the SAME shared checkout, and the site deploys
  # run concurrently: without a lock two fetches fight over
  # refs/remotes/origin/main ("cannot lock ref ...: is at X but expected Y",
  # seen on 2026-10-28 when four consumers deployed at once).
  SHARED_LOCK="/tmp/$(basename "$SHARED_DIR").deploy.lock"
  exec 9>"$SHARED_LOCK"
  if ! flock -w 180 9; then
    echo "FATAL: could not lock the shared checkout ($SHARED_LOCK)" >&2
    exit 1
  fi
  SHARED_BRANCH="$(git -C "$SHARED_DIR" rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
  case "$SHARED_BRANCH" in
    ""|HEAD) SHARED_BRANCH="main" ;;
  esac
  if ! git -C "$SHARED_DIR" fetch --quiet --prune origin "$SHARED_BRANCH"; then
    flock -u 9
    exec 9>&-
    echo "FATAL: shared checkout fetch failed ($SHARED_DIR origin/$SHARED_BRANCH)" >&2
    exit 1
  fi
  if ! git -C "$SHARED_DIR" reset --hard "origin/$SHARED_BRANCH"; then
    flock -u 9
    exec 9>&-
    echo "FATAL: shared checkout reset failed ($SHARED_DIR origin/$SHARED_BRANCH)" >&2
    exit 1
  fi
  flock -u 9
  exec 9>&-
  break
done

# Logged before the build so a failed deploy still shows what was being shipped
# (the success line below never prints in that case).
echo "==> Deploying commit: $(git -C "$REPO_DIR" rev-parse --short HEAD 2>/dev/null || echo 'no git')"

COMPOSE_ARGS=(-f docker-compose.satellite.yml)
if [ -n "" ]; then
  COMPOSE_ARGS+=(--env-file "")
fi

# Snapshot the current image so a failed deploy can be rolled back instantly.
BASE="${IMAGE%:*}"
PREV="${BASE}:prev"
if docker image inspect "$IMAGE" >/dev/null 2>&1; then
  docker tag "$IMAGE" "$PREV"
fi

# Single rollback path shared by every failed gate (health, contract
# surfaces): restore :prev, re-check health, never trust the rollback silently.
rollback() {
  echo "!! $1 - rolling back to previous image" >&2
  if docker image inspect "$PREV" >/dev/null 2>&1; then
    docker tag "$PREV" "$IMAGE"
    docker compose "${COMPOSE_ARGS[@]}" up -d --no-build
    echo "rollback complete" >&2
    # Never trust the rollback on its own: the old image may be broken too.
    if curl -fsS -o /dev/null --max-time 8 "$HEALTH_URL"; then
      echo "rollback verified: health gate OK" >&2
    else
      echo "WARN: rollback finished but $HEALTH_URL still fails - manual intervention required" >&2
    fi
  else
    echo "no previous image to roll back to" >&2
  fi
  docker compose "${COMPOSE_ARGS[@]}" ps >&2 || true
  exit 1
}

echo "==> Build"
docker compose "${COMPOSE_ARGS[@]}" build

echo "==> Start"
docker compose "${COMPOSE_ARGS[@]}" up -d

echo "==> Health gate: $HEALTH_URL (timeout ${HEALTH_TIMEOUT}s)"
deadline=$(( $(date +%s) + HEALTH_TIMEOUT ))
until curl -fsS -o /dev/null --max-time 4 "$HEALTH_URL"; do
  if [ "$(date +%s)" -ge "$deadline" ]; then
    rollback "health check failed"
  fi
  sleep 2
done

# Best-effort Cloudflare cache purge (skipped unless .env carries the credentials).
CF_TOKEN="$(grep -E '^CLOUDFLARE_API_TOKEN=' "$REPO_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '\r' || true)"
CF_ZONE="$(grep -E '^CLOUDFLARE_ZONE_ID=' "$REPO_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '\r' || true)"
if [ -n "$CF_TOKEN" ] && [ -n "$CF_ZONE" ]; then
  echo "==> Cloudflare cache purge"
  if curl -fsS -m 15 -X POST -H "Authorization: Bearer $CF_TOKEN" \
    -H "Content-Type: application/json" -d '{"purge_everything":true}' \
    "https://api.cloudflare.com/client/v4/zones/$CF_ZONE/purge_cache" >/dev/null; then
    echo "cache purged"
  else
    echo "WARN: Cloudflare cache purge failed (continuing)" >&2
  fi
else
  echo "==> Cloudflare cache purge skipped (CLOUDFLARE_API_TOKEN/CLOUDFLARE_ZONE_ID not in .env)"
fi

# -- Contract-surface gate (generated): what crawlers fetch at the root. ------
# Runs AFTER the edge purge (stale 307s/404s must be gone first) and requires
# a direct 200 - no redirect follow - plus every body marker: ads.txt with the
# live publisher id, sitemap.xml with <loc>, robots.txt, security.txt. The
# class of bug this catches (file in git, stale image, locale router 307s the
# path) passed file-body unit tests and curl -f uptime probes while AdSense
# reported "Not found". See shared/site_surfaces + QUALITY_GATES.md.
SURFACE_URLS=(

)
for entry in "${SURFACE_URLS[@]}"; do
  [ -n "$entry" ] || continue
  url="${entry%%|*}"
  markers="${entry#*|}"
  if [ "$url" = "$entry" ]; then markers=""; fi
  code=000
  body="$(mktemp)"
  code="$(curl -sS -o "$body" -w '%{http_code}' --max-time 8 "$url" 2>/dev/null || true)"
  [ -n "$code" ] || code=000
  surface_ok=1
  if [ "$code" != "200" ]; then
    surface_ok=0
  elif [ -n "$markers" ]; then
    for m in $markers; do
      if ! grep -qF -- "$m" "$body"; then
        surface_ok=0
        break
      fi
    done
  fi
  rm -f "$body"
  if [ "$surface_ok" != 1 ]; then
    rollback "surface gate failed: $url (HTTP $code)"
  fi
  echo "surface OK: $url"
done

# -- Ops maintenance (generated): crontab self-heal + alerting check ----------
# Each deploy re-asserts this site's ops cron entries: a marker comment line
# followed by the cron line, both replaced wholesale. A wiped or hand-edited
# crontab self-heals on the next deploy - manual `crontab -e` installs stop
# being part of the scheme once deploy.sh has run once.
ensure_cron() {
  local marker="$1" line="$2" cleaned
  cleaned="$( (crontab -l 2>/dev/null || true) | awk -v m="# $marker" '$0 == m {getline; next} {print}' )"
  printf '%s\n%s\n%s\n' "$cleaned" "# $marker" "$line" | crontab -     || echo "WARN: could not update the crontab (cron entries not refreshed)" >&2
}
OPS_DIR="$REPO_DIR/deploy/vps"
CRON_SITE="callagent"
if [ -f "$OPS_DIR/backup.sh" ]; then
  ensure_cron "$CRON_SITE-backup" "17 3 * * * $OPS_DIR/backup.sh >> /var/log/site-backups.log 2>&1"
fi
if [ -f "$OPS_DIR/uptime.sh" ]; then
  ensure_cron "$CRON_SITE-uptime" "*/5 * * * * $OPS_DIR/uptime.sh >> /var/log/site-uptime.log 2>&1"
fi
if [ -f "$OPS_DIR/cert-watchdog.sh" ]; then
  ensure_cron "$CRON_SITE-watchdog" "0 */6 * * * $OPS_DIR/cert-watchdog.sh >> /var/log/site-watchdog.log 2>&1"
fi

# Dark-alerting check: uptime.sh and cert-watchdog.sh page through ALERT_URL
# (webhook) and/or ALERT_EMAIL (email). With both empty the probes still run
# and log, but nobody is paged - surface that at deploy time.
ALERT_URL_CFG="$(grep -E '^ALERT_URL=' "$REPO_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '\r' || true)"
ALERT_EMAIL_CFG="$(grep -E '^ALERT_EMAIL=' "$REPO_DIR/.env" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '\r' || true)"
if [ -z "$ALERT_URL_CFG" ] && [ -z "$ALERT_EMAIL_CFG" ]; then
  echo "WARN: ALERT_URL and ALERT_EMAIL are both empty in .env - uptime/watchdog alerts only log, nobody is paged" >&2
fi

# First watchdog report in the deploy log: a cert already expiring or an ACME
# failure surfaces the moment this deploy finishes, not at the next cron tick.
# Healthy origins print nothing (watchdog alerts go to stderr).
if [ -f "$OPS_DIR/cert-watchdog.sh" ]; then
  echo "==> Origin watchdog (first report)"
  bash "$OPS_DIR/cert-watchdog.sh" || true
fi

echo "==> Deploy OK (commit: $(git -C "$REPO_DIR" rev-parse --short HEAD 2>/dev/null || echo 'no git'))"
docker compose "${COMPOSE_ARGS[@]}" ps

# Every build leaves a dangling image and build cache behind; on a small VPS the
# disk fills in a few weeks and the *build* is what starts failing. Anything from
# the last 24h is kept, so the rollback image (:prev) and the warm cache survive.
echo "==> Prune (dangling images + build cache, older than 24h)"
docker image prune -f --filter "until=24h" >/dev/null || true
docker builder prune -f --filter "until=24h" >/dev/null || true
